<?php namespace App\Http\Controllers; use App\Models\HrCertification;use App\Models\HrProbationReview;use App\Models\HrRestrictedCase;use App\Models\User;use Illuminate\Http\Request;class HrComplianceController extends AccountBaseController{private function authorizeHr(){abort_403(!in_array(user()->permission('edit_employees'),['all'],true));}public function index(){$this->authorizeHr();$this->employees=User::allEmployees(null,false,'all',user()->company_id);$this->reviews=HrProbationReview::with('employee')->where('company_id',user()->company_id)->latest()->get();$this->certifications=HrCertification::with('employee')->where('company_id',user()->company_id)->latest()->get();$this->cases=HrRestrictedCase::where('company_id',user()->company_id)->latest()->get();return view('hr-compliance.index',$this->data);}public function probation(Request $r){$this->authorizeHr();$d=$r->validate(['employee_id'=>'required|exists:users,id','review_day'=>'required|in:30,60,90','due_date'=>'required|date']);HrProbationReview::updateOrCreate(['employee_id'=>$d['employee_id'],'review_day'=>$d['review_day']],$d+['company_id'=>user()->company_id]);return back()->with('success','Probation review saved.');}public function certification(Request $r){$this->authorizeHr();$d=$r->validate(['employee_id'=>'required|exists:users,id','name'=>'required|string|max:255','expires_at'=>'nullable|date']);HrCertification::create($d+['company_id'=>user()->company_id]);return back()->with('success','Certification saved.');}public function restrictedCase(Request $r){$this->authorizeHr();$d=$r->validate(['employee_id'=>'nullable|exists:users,id','category'=>'required|string|max:100','details'=>'required|string|max:5000']);HrRestrictedCase::create($d+['company_id'=>user()->company_id,'created_by'=>user()->id]);return back()->with('success','Restricted case created.');}}
